public class Main {
    public static void main(String[] args) {
        int[] nums = {5, 2, 4, 1};
        for (int pass = 0; pass < nums.length - 1; pass++) {
            for (int i = 0; i < nums.length - 1 - pass; i++) {
                if (nums[i] > nums[i + 1]) {
                    int temp = nums[i];
                    nums[i] = nums[i + 1];
                    nums[i + 1] = temp;
                }
            }
        }
        System.out.println(java.util.Arrays.toString(nums));
    }
}
